import { released } from "./release";

const P = released("2026-11-13");

const s = (heading, ...paragraphs) => [heading, paragraphs];

// Vertical ASO playbooks for categories not yet covered in the library.
// The shared closing sections give each guide the same practical checklist.
const closing = (topic, link) => [
  s(`Competitor research for ${topic}`, `List the ten apps that rank for your main keywords in each target country. Record their titles, subtitles, first screenshots, ratings, pricing and recent updates, then read their one- to three-star reviews. Repeated complaints show the gaps your listing can promise to fill, and the words reviewers use are often keywords worth targeting.`, `Repeat the review monthly, since competitors in ${topic} change creatives and pricing often. Our [competitor ASO analysis](/blog/competitor-aso-analysis/) guide includes a template.`),
  s("Custom pages for different audiences", `Different users search for ${topic} with different goals. Custom product pages on the App Store and custom store listings on Google Play let you show each audience the screenshots and message that fit their search or ad campaign, without changing the default page.`, "Start with your two largest audiences and compare their conversion with the default page."),
  s(`Keeping the listing fresh`, `Users and store algorithms notice active apps. Update screenshots when you ship major features, rotate promotional text and in-app events around seasonal moments, and write release notes that explain what changed for users of ${topic}. Regular, meaningful updates also give you chances to fix issues raised in reviews and to test new messaging.`, "Plan a light listing refresh every quarter and a deeper creative test at least twice a year, logging each change so its effect on conversion can be measured."),
  s("When to get outside help", `If rankings and conversion stall after several months of testing, an outside review can spot issues that are hard to see from inside the team, such as keyword themes with the wrong intent or screenshots that do not match how users describe ${topic}.`, "An [ASO audit](/blog/aso-audit-checklist/) is a practical first step before larger changes."),
  s(`Measuring ASO for ${topic}`, `Track impressions, product page views, conversion rate and first-time downloads by keyword theme and country in App Store Connect and Play Console, and pair them with activation and retention from your analytics. A keyword that brings many installs but few active users is not a win for ${topic}.`, `Annotate every metadata, screenshot and pricing change so you can link results to actions, as described in our [ASO KPIs](/blog/aso-kpis-metrics/) guide.`),
  s("A 30-day action plan", `Week one: research keywords with store autocomplete and competitor listings, and read competitors' low-star reviews. Week two: rewrite the title, subtitle or short description and keyword field around the strongest themes. Week three: redesign the first three screenshots around the main outcome and start a native A/B test. Week four: add a rating prompt after a success moment and review results.`, `Repeat the cycle monthly, focusing each round on the weakest step in the funnel. See [${link[0]}](${link[1]}) for related tactics.`),
];

